-- ============================================================================
-- HELD DECISIONS (HD, 2026-09-22): seismolord.
--
-- Spec: docs/graded-field-audit/hd/seismolord.json. The new keys come from
-- tools/course-waves/w5/seismolord/fields.json,
-- written by the course's engine generator and re-checked in CI.
--
-- ADVANCED
--   Owner decision 2026-09-22 (lead recommendation approved): re-key the two
--   advanced fields that did not discriminate. tune25_amp (0.1155947595834732,
--   tol 0.002) was wider than the tuning amplitude's whole spread over every
--   panel frequency (0.1155948 at 20, 25, 40 and 50 Hz, 0.1157008 at 15 Hz), so
--   any wedge run passed it; tune25_iso_ratio (1.4449345270902185, tol 0.001)
--   was passed by the 20, 25, 40 and 50 Hz runs alike. Both are replaced by 25
--   Hz readings at a stated bed above tuning, on the falling side of the curve,
--   from the same computeWedge the Wedge explorer prints: the 'Amplitude there'
--   tile (10 dp) at 24 ms and the 'Amplitude relative to isolated' tile (4 dp)
--   at 28 ms. No other panel reading passes either (the f x T equivalent 50 Hz
--   at 14 ms prints the 28 ms ratio, a correct route), nor does any guess. The
--   lessons that printed either answer (or its amplitude or ratio form) are
--   stripped and the lessons that described the old fields are corrected. The
--   open-book label stays: the lessons still print the tuning thicknesses, the
--   theoretical value and the 6 ms bed at 40 Hz.
--   RE-KEY tune25_amp (expected 0.1155947595834732, tol 0.002)
--       -> amp25_at_24ms 'Amplitude of a 24 ms bed at 25 Hz' -, expected 0.09428644925355911, tol 0.0001
--   RE-KEY tune25_iso_ratio (expected 1.4449345270902185, tol 0.001)
--       -> ratio25_at_28ms 'Amplitude of a 28 ms bed over the isolated level at 25 Hz' -, expected 1.0688391753026658, tol 0.0002
--   PROMPT was: the peak amplitude at 25 Hz tuning,
--   PROMPT now: the amplitude of a 24 ms bed at 25 Hz,
--   PROMPT was: the ratio of the 25 Hz tuning amplitude to the
--   isolated-reflector level on the thick end of the same run,
--   PROMPT now: the ratio of the amplitude of a 28 ms bed at 25 Hz to the
--   isolated-reflector level on the thick end of the same run,
--
-- WHAT DOES NOT MOVE. Every other field (key, label, unit, expected, tol and
-- position), the title, dataset, status and the row itself.
--
-- ATTEMPTS. Tiers whose graded keys move: seismolord/advanced. Before it
-- writes, the file counts academy_capstone_attempts on each and REFUSES if any
-- exist, unless D5 allowlists that tier with the exact attempt ids (allowlist:
-- empty). Stored scores are never touched.
--
-- GUARDS. Each row must hold EITHER its post-W2-W6 form (prompt, title and
-- dataset by md5, fields as exact jsonb), which is rewritten, OR its HD form,
-- which is left alone. Anything else raises and the whole file rolls back. A
-- file that will write first checks seismolord/beginner holds its post-W2-W6
-- form (the W2-W6 batch: seismolord/beginner in its W5a form) and refuses
-- without it. Generated by docs/graded-field-audit/hd_capstones.py. SAFE TO
-- RE-RUN: a second run writes nothing.
--
-- NOT A DB STEP. The lessons that go with this file ship in the NextGen zip,
-- which must go live at nearly the same time as this apply.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_idtxt    text;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
begin
  -- seismolord / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'seismolord' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'hd seismolord refused: seismolord/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '4ccfcca366426ba684682830d039ffe0' and md5(coalesce(title, '')) = 'ec8fd9f7f4f2c1b8d742922616d86e42' and md5(coalesce(dataset, '')) = 'af3e15955763f754ebf97b9b516a907c' and fields = '[{"key": "tune25_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 25 Hz", "expected": 16}, {"key": "tune25_amp", "tol": 0.002, "unit": "-", "label": "Peak amplitude at 25 Hz tuning", "expected": 0.1155947595834732}, {"key": "tune40_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 40 Hz", "expected": 10}, {"key": "amp40_at_6ms", "tol": 0.0005, "unit": "-", "label": "Amplitude of a 6 ms bed at 40 Hz", "expected": 0.09535394608974457}, {"key": "tune25_iso_ratio", "tol": 0.001, "unit": "-", "label": "Tuning amplitude over the isolated level at 25 Hz", "expected": 1.4449345270902185}, {"key": "theory25_ms", "tol": 0.05, "unit": "ms", "label": "Theoretical tuning thickness at 25 Hz", "expected": 15.593936024673521}]'::jsonb then 'old'
              when md5(prompt) = 'b4b9a81a01b71aa752a3207cbaaecc2b' and md5(coalesce(title, '')) = 'ec8fd9f7f4f2c1b8d742922616d86e42' and md5(coalesce(dataset, '')) = 'af3e15955763f754ebf97b9b516a907c' and fields = '[{"key": "tune25_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 25 Hz", "expected": 16}, {"key": "amp25_at_24ms", "tol": 0.0001, "unit": "-", "label": "Amplitude of a 24 ms bed at 25 Hz", "expected": 0.09428644925355911}, {"key": "tune40_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 40 Hz", "expected": 10}, {"key": "amp40_at_6ms", "tol": 0.0005, "unit": "-", "label": "Amplitude of a 6 ms bed at 40 Hz", "expected": 0.09535394608974457}, {"key": "ratio25_at_28ms", "tol": 0.0002, "unit": "-", "label": "Amplitude of a 28 ms bed over the isolated level at 25 Hz", "expected": 1.0688391753026658}, {"key": "theory25_ms", "tol": 0.05, "unit": "ms", "label": "Theoretical tuning thickness at 25 Hz", "expected": 15.593936024673521}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'seismolord' and tier = 'advanced' and active;
  if v_s0 = 'other' then
    raise exception 'hd seismolord refused: seismolord/advanced matches neither its post-W2-W6 form (prompt md5 4ccfcca366426ba684682830d039ffe0) nor its HD form (prompt md5 b4b9a81a01b71aa752a3207cbaaecc2b), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its HD form
  if v_s0 = 'new' then
    raise notice 'hd seismolord: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- the W2-W6 batch must be applied first: this file joins it and applies after it
  if not exists (select 1 from public.academy_capstones where app_slug = 'seismolord' and tier = 'beginner' and active and md5(prompt) = '504c5962361e12aa8d3e607a99ecc5a2' and md5(coalesce(title, '')) = 'a3328273ed6e1f5e5cf888bd950b1ff7' and md5(coalesce(dataset, '')) = '46d7bac23cbee5cce31aab5e625bea31' and fields = '[{"key": "ubima_mean_velocity_ms", "tol": 0.05, "unit": "m/s", "label": "Mean sonic velocity in the window", "expected": 2991.2286066090837}, {"key": "ubima_twt_at_window_top_ms", "tol": 0.05, "unit": "ms", "label": "TWT at the top of the window", "expected": 1300}, {"key": "ubima_imp_max", "tol": 0.05, "unit": "(m/s)·(g/cc)", "label": "Maximum impedance in the window", "expected": 10474.98046875}, {"key": "ubima_rc_peak_abs", "tol": 0.00005, "unit": "-", "label": "Strongest reflection coefficient (abs)", "expected": 0.021212393417954445}, {"key": "ubima_rc_peak_twt_ms", "tol": 0.5, "unit": "ms", "label": "TWT of the strongest reflection", "expected": 1318}, {"key": "ubima_syn_peak_twt_ms", "tol": 0.5, "unit": "ms", "label": "TWT of the strongest synthetic amplitude (30 Hz)", "expected": 1360}]'::jsonb) then
    raise exception 'hd seismolord refused: seismolord/beginner is not in its post-W2-W6 form (prompt md5 504c5962361e12aa8d3e607a99ecc5a2); apply the W2-W6 batch first';
  end if;

  -- ATTEMPTS. A tier whose graded keys this file moves must hold no capstone
  -- attempt (a stored score is never re-scored, but a learner could be graded
  -- differently on a retry), unless D5 allowlists it with the exact attempt
  -- ids signed off. Any other attempt refuses.
  if v_s0 = 'old' then
    select coalesce(jsonb_agg(a.id::text order by a.created_at, a.id), '[]'::jsonb) into v_ids
      from public.academy_capstone_attempts a where a.app_slug = 'seismolord' and a.tier = 'advanced';
    if jsonb_array_length(v_ids) > 0 then
      if v_allow ? 'seismolord/advanced' then
        select coalesce(jsonb_agg(x), '[]'::jsonb) into v_extra
          from jsonb_array_elements(v_ids) x where not (v_allow->'seismolord/advanced') @> jsonb_build_array(x);
        if jsonb_array_length(v_extra) > 0 then
          select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_extra) x;
          raise exception 'hd seismolord refused: seismolord/advanced holds % attempt(s) outside its D5 allowlist: %', jsonb_array_length(v_extra), v_idtxt;
        end if;
        raise notice 'hd seismolord: seismolord/advanced holds % allowlisted attempt(s) (D5 sign-off); their stored scores are not touched', jsonb_array_length(v_ids);
      else
        select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_ids) x;
        raise exception 'hd seismolord refused: seismolord/advanced holds % capstone attempt(s) (%) and this file moves its graded keys; sign the tier off under D5 (allowlist with these ids) or hold it', jsonb_array_length(v_ids), v_idtxt;
      end if;
    end if;
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book, in part: some of the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now those check that you can find, read and report them correctly. A later update takes them out of the lessons and panels. Model the SAND top and base as an equal and opposite reflection pair (RC +0.08 / -0.08) in a wedge from 0 to 60 ms at a 2 ms sample rate. Read the tuning panel at 25 Hz and 40 Hz: the tuning thickness at each frequency, the amplitude of a 24 ms bed at 25 Hz, the amplitude of a 6 ms bed at 40 Hz, the ratio of the amplitude of a 28 ms bed at 25 Hz to the isolated-reflector level on the thick end of the same run, and the Kallweit-Wood theoretical tuning thickness sqrt(6)/(2*pi*f) at 25 Hz.',
           fields = '[{"key": "tune25_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 25 Hz", "expected": 16}, {"key": "amp25_at_24ms", "tol": 0.0001, "unit": "-", "label": "Amplitude of a 24 ms bed at 25 Hz", "expected": 0.09428644925355911}, {"key": "tune40_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 40 Hz", "expected": 10}, {"key": "amp40_at_6ms", "tol": 0.0005, "unit": "-", "label": "Amplitude of a 6 ms bed at 40 Hz", "expected": 0.09535394608974457}, {"key": "ratio25_at_28ms", "tol": 0.0002, "unit": "-", "label": "Amplitude of a 28 ms bed over the isolated level at 25 Hz", "expected": 1.0688391753026658}, {"key": "theory25_ms", "tol": 0.05, "unit": "ms", "label": "Theoretical tuning thickness at 25 Hz", "expected": 15.593936024673521}]'::jsonb
     where app_slug = 'seismolord' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'hd seismolord refused: seismolord/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'b4b9a81a01b71aa752a3207cbaaecc2b' and md5(coalesce(title, '')) = 'ec8fd9f7f4f2c1b8d742922616d86e42' and md5(coalesce(dataset, '')) = 'af3e15955763f754ebf97b9b516a907c' and fields = '[{"key": "tune25_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 25 Hz", "expected": 16}, {"key": "amp25_at_24ms", "tol": 0.0001, "unit": "-", "label": "Amplitude of a 24 ms bed at 25 Hz", "expected": 0.09428644925355911}, {"key": "tune40_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 40 Hz", "expected": 10}, {"key": "amp40_at_6ms", "tol": 0.0005, "unit": "-", "label": "Amplitude of a 6 ms bed at 40 Hz", "expected": 0.09535394608974457}, {"key": "ratio25_at_28ms", "tol": 0.0002, "unit": "-", "label": "Amplitude of a 28 ms bed over the isolated level at 25 Hz", "expected": 1.0688391753026658}, {"key": "theory25_ms", "tol": 0.05, "unit": "ms", "label": "Theoretical tuning thickness at 25 Hz", "expected": 15.593936024673521}]'::jsonb) from public.academy_capstones where app_slug = 'seismolord' and tier = 'advanced' and active) is not true then
    raise exception 'hd seismolord refused: seismolord/advanced does not read back as its HD form';
  end if;

  raise notice 'hd seismolord: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
